{
  "version": "1.2.0",
  "feature": "Pirate Sea Race intel online",
  "independent_review": true,
  "integration_approval": true,
  "max_verification_attempts": 3,
  "setup": [
    {
      "argv": [
        "npm",
        "ci"
      ],
      "timeout_seconds": 900
    }
  ],
  "workers": [
    {
      "node_id": "game",
      "role": "fullstack",
      "required_check_kinds": [
        "typecheck",
        "unit",
        "integration",
        "build",
        "browser"
      ],
      "owned_paths": [
        "package.json",
        "package-lock.json",
        "README.md",
        "docs/architecture.md",
        "docs/duel.md",
        "docs/encounters.md",
        "packages/simulation/package.json",
        "packages/simulation/src/netcode",
        "packages/simulation/src/encounters",
        "packages/simulation/src/step.ts",
        "packages/simulation/src/state.ts",
        "packages/simulation/src/config.ts",
        "packages/simulation/src/index.ts",
        "packages/simulation/src/input.ts",
        "packages/simulation/src/visibility.ts",
        "packages/simulation/src/simulation.test.ts",
        "packages/content/package.json",
        "packages/content/src/encounters",
        "packages/content/src/sailing.ts",
        "packages/content/src/index.ts",
        "packages/protocol",
        "packages/test-tools",
        "apps",
        "tests/integration",
        "tests/e2e",
        "scripts",
        "vitest.config.ts",
        "docs/objectives.md",
        "docs/match-online-coverage.md",
        "docs/ruins-online-coverage.md",
        "docs/fruit-kits-online-coverage.md",
        "docs/intel-online-coverage.md"
      ],
      "checks": [
        {
          "id": "typecheck",
          "kind": "typecheck",
          "argv": [
            "npm",
            "run",
            "typecheck"
          ],
          "timeout_seconds": 300,
          "scenarios": []
        },
        {
          "id": "unit",
          "kind": "unit",
          "argv": [
            "npm",
            "run",
            "test:unit"
          ],
          "timeout_seconds": 300,
          "scenarios": []
        },
        {
          "id": "integration",
          "kind": "integration",
          "argv": [
            "npm",
            "run",
            "test:integration"
          ],
          "timeout_seconds": 300,
          "scenarios": []
        },
        {
          "id": "build",
          "kind": "build",
          "argv": [
            "npm",
            "run",
            "build"
          ],
          "timeout_seconds": 600,
          "scenarios": []
        },
        {
          "id": "browser",
          "kind": "browser",
          "argv": [
            "npx",
            "--no-install",
            "playwright",
            "test",
            "--config=tests/e2e/playwright.config.ts"
          ],
          "timeout_seconds": 1800,
          "scenarios": [
            {
              "id": "join-private-match",
              "description": "One browser creates a private match from the landing page; the HUD shows the code, the protocol version, one player and a connected status."
            },
            {
              "id": "two-ships-sync",
              "description": "Two browsers join the same private match with their ships in sight of each other; one sails with the keyboard and the other browser's view shows that ship at the new server-authoritative position."
            },
            {
              "id": "sail-and-dock",
              "description": "A browser sails its ship around a shoal to an island dock with the keyboard and docks there; the HUD shows the dock and the ship stops at it."
            },
            {
              "id": "out-of-sight",
              "description": "Two browsers in one match with their ships out of sight of each other: neither view lists or draws the other ship until one sails within the sight radius, and it disappears again when it sails away."
            },
            {
              "id": "duel-practice",
              "description": "One browser opens a practice duel against the dummy, lands a jab and then a keyboard throw (J then K a frame apart); the dummy's health bar and the HUD drop by the move data's damage, and hitboxes can be shown."
            },
            {
              "id": "duel-online",
              "description": "Two browsers: one creates a duel, the other joins by its code; after the countdown the first lands a strike on the second, and both views show the same authoritative health, round clock and result, with the connection line showing input delay and corrections."
            },
            {
              "id": "sea-duel",
              "description": "Two browsers in one match are placed within grapple range; the host sails at the guest and presses J; both see the grapple telegraph, then a three-second countdown and the arena; the duel is decided; the winner returns to the sea with protection shown, and the loser sees a respawn countdown and then their ship at a dock."
            },
            {
              "id": "theft-loop",
              "description": "Two browsers moored at different islands each hold E and collect a different rubbing type; the host grapples the guest at sea, wins the duel by tapping attack keys, and picks the guest's type within five seconds; the host's HUD shows both types and more gold, the guest's shows the loss."
            },
            {
              "id": "full-match",
              "description": "Two browsers: the host starts a private match from the lobby, both see the ready countdown and the match timer; the host collects both rubbing types, sees the full-set reveal and the route, sails to the final island's claim tile and holds E for ten seconds; both browsers show the results with the host as the winner."
            },
            {
              "id": "match-deadline",
              "description": "Two browsers start a private match from the lobby with test-only short timings; nobody claims; the timer runs out; both browsers show the results with the no-winner deadline headline, and the route compass is shown inactive while no route is known."
            },
            {
              "id": "ruin-solve",
              "description": "One browser moored at an island opens its ruin with R and reads the clue from the page; the test derives the answer from the displayed clue only, submits it, sees '+40 gold' and the island unlocked, then holds E to collect the rubbing."
            },
            {
              "id": "fruit-duel",
              "description": "One browser moors at a pedestal's dock, presses F, reads the kit name from the panel, holds F for three seconds and sees its HUD show Ember; it grapples the second browser at sea, casts the flame bolt (U) in the arena, both browsers see the bolt drawn, and the second browser's health bar drops by the bolt's damage."
            },
            {
              "id": "rumor-journal",
              "description": "Two browsers start a private match; the host opens the journal with Tab and reads its start rumor (a type and an island or sector name) from the page, sails to a dock, moors, buys a targeted rumor and sees its gold drop by 25 and a new journal entry marked targeted; the guest's page never shows the host's rumors."
            }
          ]
        }
      ]
    }
  ]
}

